INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('94f496b6-5e15-4a5a-9bd2-0cb1885864bf'::uuid, 'card_description', 'An iron folding chair turned up among the grave goods in these Roman mounds. Diggers in the 19th century also found human ashes inside glass vessels, kept in large wooden chests.', 'At Bartlow Hills the tallest barrow rises 15 metres, the largest Roman barrow north of the Alps. Excavators found walled graves with cremains in glass vessels, kept in large wooden chests.', 'teaser-card-s043-rollback:94f496b6-5e15-4a5a-9bd2-0cb1885864bf:card_description', 'rollback of teaser-card-s043: card_description ''At Bartlow Hills the tallest barrow rises 15 metres, the largest Roman barrow north of the Alps. Excavators found walled graves with cremains in glass vessels, kept in large wooden chests.'' restored on Bartlow Hills', '7a285fca60f9be0161b785108727ba0d262a6d1810ad48b6e46aac4811c98540|d5b670ab5b4bcacaf04e307be9f92bd2a22644b22c24dace7bb071a7af909586|d5b670ab5b4bcacaf04e307be9f92bd2a22644b22c24dace7bb071a7af909586', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An iron folding chair turned up among the grave goods in these Roman mounds. Diggers in the 19th century also found human ashes inside glass vessels, kept in large wooden chests."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "an iron folding chair was found [S5]; it was found among the funerary goods [S5]; the mounds are Roman [S1]; excavators worked in the 19th century [S4]; they found human cremated remains [S4]; the remains were in glass vessels [S4]; the vessels were stored in large wooden chests [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An iron folding chair turned up in these mounds (Bartlow Hills) [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The iron folding chair was among the grave goods [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The mounds are Roman [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow]; Diggers excavated the mounds in the 19th century [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The 19th-century diggers found human ashes [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The human ashes were inside glass vessels [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The glass vessels with the ashes were kept in wooden chests [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Great_Britain/_Periods/Roman/_Texts/WARREB/8*.html]; The wooden chests were large [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow]"}]'::jsonb),
    ('951c140b-1698-4495-9c6b-c78254c2b4cd'::uuid, 'card_description', 'An upturned tree root sat at the heart of this timber circle. Around the root stood 55 split oak trunks, all but one with bark facing out; a trunk with a narrow Y fork let people in.', 'Near Old Hunstanton in Norfolk stood Seahenge: 55 split oak trunks around an upturned tree root, built in the spring-summer of 2049 BC, one trunk with a narrow Y fork permitting access.', 'teaser-card-s043-rollback:951c140b-1698-4495-9c6b-c78254c2b4cd:card_description', 'rollback of teaser-card-s043: card_description ''Near Old Hunstanton in Norfolk stood Seahenge: 55 split oak trunks around an upturned tree root, built in the spring-summer of 2049 BC, one trunk with a narrow Y fork permitting access.'' restored on Seahenge', '5048699e8774123ed6a8440fc4b28d8bf65ff8120e8c5af995c1319397de2d87|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An upturned tree root sat at the heart of this timber circle. Around the root stood 55 split oak trunks, all but one with bark facing out; a trunk with a narrow Y fork let people in."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "an upturned tree root stood at the centre [S2]; the site is a timber circle [S2]; a ring of trunks surrounded the root [S2, S3]; there were 55 trunks [S3]; they were split oak trunks [S3]; all but one had their bark facing outwards [S5]; one trunk had a narrow Y fork [S6]; the fork gave access to the central area [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An upturned tree root sat at the heart of this timber circle (Seahenge) [SUPPORTED: https://artsandculture.google.com/story/seahenge-lynn-museum/pwVhBxecshzaMQ?hl=en]; The monument is a timber circle [SUPPORTED: https://www.heritage.norfolk.gov.uk/record-details?MNF33771]; 55 trunks stood around the root [SUPPORTED: https://artsandculture.google.com/story/seahenge-lynn-museum/pwVhBxecshzaMQ?hl=en]; The trunks were split [SUPPORTED: https://link.springer.com/article/10.1007/s10708-024-11088-5]; The trunks were oak [SUPPORTED: https://www.heritage.norfolk.gov.uk/record-details?MNF33771]; All but one of the trunks had their bark facing out [SUPPORTED: https://www.heritage.norfolk.gov.uk/record-details?MNF33771]; One trunk had a narrow Y fork [SUPPORTED: https://link.springer.com/article/10.1007/s10708-024-11088-5]; The trunk with the Y fork let people in (served as the way into the circle) [SUPPORTED: https://link.springer.com/article/10.1007/s10708-024-11088-5]"}]'::jsonb),
    ('99c67365-3376-46ae-9e60-0d2ec03bfff4'::uuid, 'card_description', 'Coins from Mark Anthony to Gratian lay in this walled spring. With them lay a relief of three water nymphs, the head of a male statue and ten altars to a goddess and Minerva.', 'A walled spring called Coventina''s Well held 13,487 coins, a relief of three water nymphs and altars to the goddess Coventina, some showing her reclining and partially clothed.', 'teaser-card-s043-rollback:99c67365-3376-46ae-9e60-0d2ec03bfff4:card_description', 'rollback of teaser-card-s043: card_description "A walled spring called Coventina''s Well held 13,487 coins, a relief of three water nymphs and altars to the goddess Coventina, some showing her reclining and partially clothed." restored on Coventina', '3f9d6ee982b4906548f2ad7f4beb8507d9080d38c951f44e124315e1da683244|a6ae86f56725ea82f507bd4a21f06377ac00ca6096868683d1a11d8ebde805fd|a6ae86f56725ea82f507bd4a21f06377ac00ca6096868683d1a11d8ebde805fd', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Coins from Mark Anthony to Gratian lay in this walled spring. With them lay a relief of three water nymphs, the head of a male statue and ten altars to a goddess and Minerva."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "coins were found at the site [S3]; the coins date from Mark Anthony to Gratian [S3]; the coins lay in the spring [S3]; the spring is walled / lies in a walled enclosure [S1, S2]; a relief of three water nymphs lay with the coins [S3]; the head of a male statue lay with the coins [S3]; ten altars lay with the coins [S3]; the altars are to a goddess and Minerva [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Coins lay in this spring (Coventina''s Well at Carrawburgh). [SUPPORTED: http://midgleywebpages.com/coventina.html]; The earliest coins date from Mark Anthony. [SUPPORTED: http://midgleywebpages.com/coventina.html]; The latest coins date from Gratian. [SUPPORTED: http://midgleywebpages.com/coventina.html]; The spring is walled. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; A relief lay with the coins. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; The relief shows three water nymphs. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; The head of a male statue lay with them. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; Ten altars lay with them. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; The altars were dedicated to a goddess (Coventina). [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]; The altars were also dedicated to Minerva. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/temple-of-mithras-carrawburgh-hadrians-wall/history/]"}]'::jsonb),
    ('9fe64aa7-1b1a-4074-b6c2-f2d236938ab4'::uuid, 'card_description', 'A wooden structure of unknown use was found inside this small Roman fort. Its only gate faced north, toward the frontier, behind a rampart and a ditch 5 meters wide and 1.5 meters deep.', 'Am Forsthofweg, a Roman fortlet on the Limes, is an almost square earthwork whose only gate faced north. Inside, a wooden construction of around 45 square meters was found, its use unknown.', 'teaser-card-s043-rollback:9fe64aa7-1b1a-4074-b6c2-f2d236938ab4:card_description', 'rollback of teaser-card-s043: card_description ''Am Forsthofweg, a Roman fortlet on the Limes, is an almost square earthwork whose only gate faced north. Inside, a wooden construction of around 45 square meters was found, its use unknown.'' restored on Am Forsthofweg', 'e91aa68993888e70e304810d793303050cc03fed23ad331599e2df131f3db541|9b5cfb945f9de436abec4f9db4ba3bf5b3ca8a42104e30279ba6f425583dcf01|9b5cfb945f9de436abec4f9db4ba3bf5b3ca8a42104e30279ba6f425583dcf01', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-014", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A wooden structure of unknown use was found inside this small Roman fort. Its only gate faced north, toward the frontier, behind a rampart and a ditch 5 meters wide and 1.5 meters deep."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a wooden structure was found inside the fort [S8]; its function is unknown [S8]; the site is a small fort [S1]; the fort is Roman [S1]; the fort had only one gate [S7]; the gate faced north [S7]; the gate faced toward the frontier (Limes frontline) [S7]; a rampart and a ditch formed the defence line in front of the fort [S6]; the ditch was 5 metres wide and 1.5 metres deep [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-025 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A wooden structure of unknown use was found inside this fort (Am Forsthofweg) [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The fort is small [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; It is a Roman fort [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The fort had only one gate [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The gate faced north [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The gate faced toward the frontier (the Limes) [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The fort had a rampart [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The fort had a ditch 5 meters wide [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]; The ditch was 1.5 meters deep [SUPPORTED: https://de.wikipedia.org/wiki/Kleinkastell_%E2%80%9EAm_Forsthofweg%E2%80%9C]"}]'::jsonb),
    ('a2b571fa-4aa3-4c23-b5f0-13c5552ce870'::uuid, 'card_description', 'Francisco Pizarro took this royal Inca estate for himself in the 1530s. It had belonged to an Inca emperor, and the estate ran for 15 kilometres up and down the Sacred Valley.', 'Fitted stonework, gatehouses and the foundation of a great hall mark Quispiguanca, royal estate of the Inca emperor Huayna Capac, taken by Francisco Pizarro as his encomienda in the 1530s.', 'teaser-card-s043-rollback:a2b571fa-4aa3-4c23-b5f0-13c5552ce870:card_description', 'rollback of teaser-card-s043: card_description ''Fitted stonework, gatehouses and the foundation of a great hall mark Quispiguanca, royal estate of the Inca emperor Huayna Capac, taken by Francisco Pizarro as his encomienda in the 1530s.'' restored on Quispiguanca', '526eb4dc9d1177555ad0bfc8a3d7b959e395010543fcea7f751e94af69457ed6|024d40a1ad7310c0faed13c55907d30b68803eb316278f0ffcf2c0c33c2a1642|024d40a1ad7310c0faed13c55907d30b68803eb316278f0ffcf2c0c33c2a1642', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Francisco Pizarro took this royal Inca estate for himself in the 1530s. It had belonged to an Inca emperor, and the estate ran for 15 kilometres up and down the Sacred Valley."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-005 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Francisco Pizarro appropriated the estate for himself [S8]; he did so in the 1530s [S8]; the site is a royal Inca estate [S1]; the estate had belonged to an Inca emperor [S1, S8]; the estate extended for 15 kilometres up and down the Sacred Valley [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wav