    ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'card_description', 'Two crests once ran across the top of this warrior''s helmet and down its back. Dug up in 2008 from a burial of the first century BC, the helmet was the most remarkable object of the grave.', NULL, 'teaser-card-s043-rollback:a2c6e1bf-1538-43c4-ad4a-65a0186193a7:card_description', 'rollback of teaser-card-s043: card_description None restored on North Bersted Man', 'de2f9c50e6295eaa9563208b94b9fdc61e60d2659fc5e7d79ee685bfcbd86a25|16d5bd81ed1bb7966f42c76cd407ae33685c34cffd6948fa1bbdf6e83aa6130f|16d5bd81ed1bb7966f42c76cd407ae33685c34cffd6948fa1bbdf6e83aa6130f', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite2-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two crests once ran across the top of this warrior''s helmet and down its back. Dug up in 2008 from a burial of the first century BC, the helmet was the most remarkable object of the grave."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check2-002 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a warrior''s burial [S1]; the warrior had a helmet [S5]; two crests once ran across the top of the helmet [S6]; the crests ran down the helmet''s back [S6]; it was dug up in 2008 [S1]; the burial dates to the first century BC [S4]; the helmet was the most remarkable object of the grave [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two crests once ran across the top of this warrior''s helmet and down its back [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; The helmet had two crests [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; A crest ran across the top of the helmet [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; A crest ran down the back of the helmet [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; The buried man was a warrior [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; The helmet was dug up in 2008 [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; It came from a burial (grave) [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; The burial is of the first century BC [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]; The helmet was the most remarkable object of the grave [SUPPORTED: https://archaeology.co.uk/articles/features/arms-and-the-man.htm]"}]'::jsonb),
    ('a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290'::uuid, 'card_description', 'A groundsman clearing land for a runway found Iron Age metalwork. Over 150 objects came out of the peat, apparently placed in a small lake as offerings, the first an iron chain for slaves.', 'In 1942, as peat was dug for a runway extension, over 150 Iron Age metal objects surfaced at Llyn Cerrig Bach, apparently votive offerings. The first was an iron gang chain for slaves.', 'teaser-card-s043-rollback:a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290:card_description', 'rollback of teaser-card-s043: card_description ''In 1942, as peat was dug for a runway extension, over 150 Iron Age metal objects surfaced at Llyn Cerrig Bach, apparently votive offerings. The first was an iron gang chain for slaves.'' restored on Llyn Cerrig Bach', '15282ec6ece6e9fea5cc1d283b5729fd2b5f090aca2f6f994522986fcdb76a18|e5ecfaa24efb2afedd41bb84e60f239b6408a4df75d6d3d7cea5d6572bfd9cf5|e5ecfaa24efb2afedd41bb84e60f239b6408a4df75d6d3d7cea5d6572bfd9cf5', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-015", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A groundsman clearing land for a runway found Iron Age metalwork. Over 150 objects came out of the peat, apparently placed in a small lake as offerings, the first an iron chain for slaves."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a groundsman made the find [S4]; the find was made while ground was cleared for a runway [S4]; the finds are Iron Age metalwork [S2, S3]; there were over 150 objects [S2]; the objects came out of the peat [S5]; they were apparently placed in the lake as offerings [S2]; the lake is small [S1]; the first object found was an iron chain [S6]; the chain was used for slaves [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-026 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A groundsman found the metalwork [SUPPORTED: https://coflein.gov.uk/en/sites/401097]; He was clearing land for a runway [SUPPORTED: https://www.dailypost.co.uk/news/local-news/daughter-man-who-found-llyn-2652970]; The metalwork is Iron Age [SUPPORTED: https://the-past.com/feature/the-riddle-of-the-lake-llyn-cerrig-bach-and-iron-age-anglesey/]; Over 150 objects were found [SUPPORTED: https://coflein.gov.uk/en/sites/401097]; The objects came out of the peat [SUPPORTED: https://museum.wales/collections/online/object/3d333bab-eb3a-378c-97f0-a1ca1caf8765/Iron-Age-iron-gang-chain/]; The objects were apparently placed in a lake as offerings [SUPPORTED: https://coflein.gov.uk/en/sites/401097]; The lake is small [SUPPORTED: https://coflein.gov.uk/en/sites/401097]; The first object found was a chain [SUPPORTED: https://www.dailypost.co.uk/news/local-news/daughter-man-who-found-llyn-2652970]; The chain is of iron [SUPPORTED: https://museum.wales/collections/online/object/3d333bab-eb3a-378c-97f0-a1ca1caf8765/Iron-Age-iron-gang-chain/]; The chain was for slaves [SUPPORTED: https://museum.wales/collections/online/object/3d333bab-eb3a-378c-97f0-a1ca1caf8765/Iron-Age-iron-gang-chain/]"}]'::jsonb),
    ('a6492846-5963-4307-8ffc-ea06bb554b1e'::uuid, 'card_description', 'Upright stones shrink from south-west to north-east along this prehistoric tomb. The tomb measures about 4.5 by 2 metres, and the largest of its side stones stands at the entrance.', 'In County Monaghan, near the Cavan border, Lisnadarragh Wedge Tomb is walled by 20 orthostats that shrink from south-west to north-east, the largest, at the entrance, 1.8 metres high.', 'teaser-card-s043-rollback:a6492846-5963-4307-8ffc-ea06bb554b1e:card_description', 'rollback of teaser-card-s043: card_description ''In County Monaghan, near the Cavan border, Lisnadarragh Wedge Tomb is walled by 20 orthostats that shrink from south-west to north-east, the largest, at the entrance, 1.8 metres high.'' restored on Lisnadarragh Wedge Tomb', 'ddd0b544cf22a754f289589e65fdf63af15a705645e45179c448486c5a24ea5e|b85a57e498b1ad92c1dc071e79b0f43c0830f3df8c8a2804c7ca2fe240130253|b85a57e498b1ad92c1dc071e79b0f43c0830f3df8c8a2804c7ca2fe240130253', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Upright stones shrink from south-west to north-east along this prehistoric tomb. The tomb measures about 4.5 by 2 metres, and the largest of its side stones stands at the entrance."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb''s sides are formed by upright stones [S3]; the upright stones decrease in size from south-west to north-east [S3]; the site is a prehistoric tomb [S1]; the tomb measures about 4.5 by 2 metres [S2]; the largest side stone stands at the entrance [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Upright stones shrink from south-west to north-east along this tomb [SUPPORTED: https://cdn.ringofgullion.org/2015/01/Ulster-s-Changing-Borders-Report-.pdf]; The tomb is prehistoric [SUPPORTED: https://cdn.ringofgullion.org/2015/01/Ulster-s-Changing-Borders-Report-.pdf]; The tomb measures about 4.5 metres in length [SUPPORTED: https://visionsofthepastblog.com/2013/09/02/lisnadarragh-wedge-tomb-co-monaghan/]; The tomb measures about 2 metres in width [SUPPORTED: https://visionsofthepastblog.com/2013/09/02/lisnadarragh-wedge-tomb-co-monaghan/]; The largest of its side stones stands at the entrance [SUPPORTED: https://visionsofthepastblog.com/2013/09/02/lisnadarragh-wedge-tomb-co-monaghan/]"}]'::jsonb),
    ('a72bf9fc-f2ef-4f84-b322-f9707dac50f5'::uuid, 'card_description', 'Coastal erosion was believed to have largely destroyed this stone temple. In 2015, its remains turned out to survive, along with a previously unrecorded megalithic structure nearby.', 'Built between 3600 and 3000 BC and thought largely lost to coastal erosion, Xrobb l-Għaġin Temple survives, as 2015 investigations revealed, with an unrecorded megalithic structure nearby.', 'teaser-card-s043-rollback:a72bf9fc-f2ef-4f84-b322-f9707dac50f5:card_description', 'rollback of teaser-card-s043: card_description ''Built between 3600 and 3000 BC and thought largely lost to coastal erosion, Xrobb l-Għaġin Temple survives, as 2015 investigations revealed, with an unrecorded megalithic structure nearby.'' restored on Xrobb l-Għaġin Temple', '33e658e0ebb8166d991abc88f9123540816fde3d70cb59d7144f12580af3a404|d056fade57b1f3ef3c8277356531fbf19a149ac74ae6547e80e8e3762a0f19db|d056fade57b1f3ef3c8277356531fbf19a149ac74ae6547e80e8e3762a0f19db', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Coastal erosion was believed to have largely destroyed this stone temple. In 2015, its remains turned out to survive, along with a previously unrecorded megalithic structure nearby."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a stone (megalithic) temple [S1]; it was believed to have been largely destroyed [S3]; the believed cause was coastal erosion [S3]; investigations in 2015 showed its remains survive [S3]; a previously unrecorded megalithic structure lies nearby [S3]; the nearby structure was revealed in 2015 [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Coastal erosion was believed to have largely destroyed this temple [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]; The site is a stone (megalithic) temple [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]; Its remains turned out to survive [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]; The survival of its remains came to light in 2015 [SUPPORTED: https://heritagemalta.mt/news/heritage-malta-reaches-exciting-final-phase-of-xrobb-l-ghagin-project/]; A previously unrecorded megalithic structure turned up as well [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]; The unrecorded structure is nearby [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]; The unrecorded structure came to light in 2015 [SUPPORTED: https://www.um.edu.mt/library/oar/bitstream/123456789/23414/1/MAR_10_BorgGrima.pdf]"}]'::jsonb),
    ('ab699722-9c7e-464a-b507-74a21078411c'::uuid, 'card_description', 'Iron furnaces and pottery kilns shared a Roman town with this temple. Remains from the late Iron Age date from 30 BC, and a Roman road 7 metres wide predates the one through the village.', 'A 2019 dig at Newington in Kent rediscovered a Roman town of iron furnaces and pottery kilns, the temple now called Watling Temple, and a 7 metres wide road older than Watling Street.', 'teaser-card-s043-rollback:ab699722-9c7e-464a-b507-74a21078411c:card_description', 'rollback of teaser-card-s043: card_description ''A 2019 dig at Newington in Kent rediscovered a Roman town of iron furnaces and pottery kilns, the temple now called Watling Temple, and a 7 metres wide road older than Watling Street.'' restored on Watling Temple', '6e58ced887de1d738afafeba47b5bdbf9c58c6eaa42ff3b905fef8565dd9eff2|6119f0ba9d52fcdd57d00c4ec05816ee00bd9b5fc84691e1d2da0f8a6ce536c3|6119f0ba9d52fcdd57d00c4ec05816ee00bd9b5fc84691e1d2da0f8a6ce536c3', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-015", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Iron furnaces and pottery kilns shared a Roman town with this temple. Remains from the late Iron Age date from 30 BC, and a Roman road 7 metres wide predates the one through the village."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "iron furnaces were found at the town [S2]; pottery kilns were found at the town [S2]; the temple stood within a Roman town [S1]; there are late Iron Age remains [S2]; those remains date from 30 BC [S2]; a Roman road 7 metres wide was found [S2]; that road predates the Roman road that runs through the village [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Iron furnaces shared a Roman town with this temple. [SUPPORTED: https://www.swatarchaeology.co.uk/news.aspx]; Pottery kilns shared a Roman town with this temple. [SUPPORTED: https://www.swatarchaeology.co.uk/news.aspx]; The temple stood in a Roman town. [SUPPORTED: https://web.archive.org/web/20190923113644/http://www.newingtonhistorygroup.btck.co.uk/WatlingPlaceexcavation]; Remains from the late Iron Age date from 30 BC. [SUPPORTED: https://web.archive.org/web/20190923113644/http://www.newingtonhistorygroup.btck.co.uk/WatlingPlaceexcavation]; A Roman road 7 metres wide was found there. [SUPPORTED: https://www.swatarchaeology.co.uk/news.aspx]; The 7-metre road predates the Roman road through the village. [SUPPORTED: https://www.swatarchaeology.co.uk/news.aspx]; A Roman road runs through the village. [SUPPORTED: https://www.kentonline.co.uk/sittingbourne/news/forgotten-roman-village-found-on-building-site-205217/]"}]'::jsonb),
    ('acec1746-35a0-4d0e-be03-1d240bad074c'::uuid, 'card_description', 'A pyramid over 10 metres high rises on a wooded hilltop here. The pyramid stands at the north end of at least three groups of ruins on a north-south line, about 18 kilometres from Tikal.', 'On a wooded hilltop in Petén, a Maya pyramid over 10 metres high rises among the collapsed structures of El Temblor, and a damaged stela still stands to its east.', 'teaser-card-s043-rollback:acec1746-35a0-4d0e-be03-1d240bad074c:card_description', 'rollback of teaser-card-s043: card_description ''On a wooded hilltop in Petén, a Maya pyramid over 10 metres high rises among the collapsed structures of El Temblor, and a damaged stela still stands to its east.'' restored on El Temblor', '901c93e2edd9934f03c881ebee025e9bce868a307c0cec03f5a26eaf9becd845|9ea52bb03a34718472640ffa64c66bcff5ec263af79fd493a27a5119af0f1104|9ea52bb03a34718472640ffa64c66bcff5ec263af79fd493a27a5119af0f1104', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A pyramid over 10 metres high rises on a wooded hilltop here. The pyramid stands at the north end of at least three groups of ruins on a north-south line, about 18 kilometres from Tikal."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-005 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site has a pyramid over 10 metres high [S5]; the pyramid stands on a wooded hilltop [S5]; the ruins form at least three groups [S4]; the groups lie on a north-south axis [S4]; the pyramid is in the northernmost group [S5]; the site is about 18 kilometres from Tikal [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A pyramid over 10 metres high rises here. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]; The pyramid rises on a wooded hilltop. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]; The pyramid stands at the north end of the groups of ruins. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]; The site has at least three groups of ruins. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]; The groups lie on a north-south line. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]; The site is about 18 kilometres from Tikal. [SUPPORTED: https://www.redalyc.org/journal/2470/247062474003/html/]"}]'::jsonb),
    ('ae3b5deb-3b9c-42ec-8610-445c99f5b1a8'::uuid, 'card_description', 'No evidence shows the Roman general in this hillfort''s name ever came here. The earthworks stretch 730 m from north to south, on a hill with the River Avon to the south.', 'Less than 3 kilometres from Stonehenge, the Iron Age hillfort of Vespasian''s Camp carries a Roman general''s name, given in the 16th century, yet no evidence suggests he ever came here.', 'teaser-card-s043-rollback:ae3b5deb-3b9c-42ec-8610-445c99f5b1a8:card_description', 'rollback of teaser-card-s043: card_description "Less than 3 kilometres from Stonehenge, the Iron Age hillfort of Vespasian''s Camp carries a Roman general''s name, given in the 16th century, yet no evidence suggests he ever came here." restored on Vespasian''s Camp', '73e9d028b0cbdc2edbea38f993d1a7ce3fcc8c5f3c8bfe785910606169b2720b|ea1727a2b1895bfe0b78f596b9622ed54e8efebbc30c88c1c8c24bbdb070b722|ea1727a2b1895bfe0b78f596b9622ed54e8efebbc30c88c1c8c24bbdb070b722', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-016", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "No evidence shows the Roman general in this hillfort''s name ever came here. The earthworks stretch 730 m from north to south, on a hill with the River Avon to the south."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a hillfort [S1]; the hillfort''s name contains a Roman general [S4, S5]; there is no evidence that this Roman general ever came to the hillfort [S5]; the earthworks are 730 m long [S6]; they are aligned north to south [S6]; the hillfort is on a hill [S2]; the River Avon lies on its southern side [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-027 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "No evidence shows the Roman general in this hillfort''s name ever came here. [SUPPORTED: https://www.buckingham.ac.uk/research/hri/fellows/jacques/18thcentury/]; The hillfort''s name is that of a Roman general. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=17389]; The site is a hillfort. [SUPPORTED: https://www.buckingham.ac.uk/research/hri/fellows/jacques/18thcentury/]; The earthworks stretch 730 m. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=17389]; The 730 m run from north to south. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=17389]; The hillfort is on a hill. [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0407.html]; The River Avon lies to the south of the hill. [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN0407.html]"}]'::jsonb),
    ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'card_description', 'A carved stone slab was found in the northern group of this Maya site. Eleven residential areas lie in its two groups, and the site is considered a satellite of El Mirador.', 'The site is divided into North and South Groups, located approximately 400 metres apart.', 'teaser-card-s043-rollback:b43e7f32-5f59-4370-9cf0-43c3f159e4e3:card_description', 'rollback of teaser-card-s043: card_description ''The site is divided into North and South Groups, located approximately 400 metres apart.'' restored on La Muerta', '518323486002de42a3c01adfa6f303f127904aa3cfcadf747bbc4007415a2028|feb0e3fa6bdf100c499db9d4740515c47544fdf9fe004254ff639b2a3b596d44|feb0e3fa6bdf100c499db9d4740515c47544fdf9fe004254ff639b2a3b596d44', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A carved stone slab was found in the northern group of this Maya site. Eleven residential areas lie in its two groups, and the site is considered a satellite of El Mirador."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-007 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a carved stone slab (sculptured stela) was found at the site [S8]; it was found in the northern group [S8]; the site is a Maya site [S1]; the site has two groups [S5]; eleven residential areas lie in the two groups [S6]; the site is considered a satellite of El Mirador [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A carved stone slab was found at this site [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]; The slab was found in the northern group of this site [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]; This is a Maya site [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]; The site has two groups [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]; Eleven residential areas lie in its two groups [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]; The site is considered a satellite of El Mirador [SUPPORTED: https://web.archive.org/web/20110707181652/http://www.asociaciontikal.com/pdf/07%20-%20Suyuc%20y%20Balcarcel.04.pdf]"}]'::jsonb),
    ('b69f338c-fb2b-4860-9935-61e93e27ddf3'::uuid, 'card_description', 'Only about 20 cm thick, two stones stand about 3 m apart on open grass. Thought to date from the Bronze Age, the pair rises between two low hills, lined up northeast to southwest.', 'Two slender stones, each about 3 m high yet only about 20 cm thick, stand on Holy Island: the Penrhos Feilw Standing Stones, thought to be Bronze Age, their origins and purpose unclear.', 'teaser-card-s043-rollback:b69f338c-fb2b-4860-9935-61e93e27ddf3:card_description', 'rollback of teaser-card-s043: card_description ''Two slender stones, each about 3 m high yet only about 20 cm thick, stand on Holy Island: the Penrhos Feilw Standing Stones, thought to be Bronze Age, their origins and purpose unclear.'' restored on Penrhos Feilw Standing Stones', '1c2fba3f81361e76470466bf99364f5ce54bfa2b1f542244e9644e7c8c4cdc2b|72b68dc9e9cb1f7b40d87f6344c3a72acd333c1c6024feebfbeace91d8f69760|72b68dc9e9cb1f7b40d87f6344c3a72acd333c1c6024feebfbeace91d8f69760', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Only about 20 cm thick, two stones stand about 3 m apart on open grass. Thought to date from the Bronze Age, the pair rises between two low hills, lined up northeast to southwest."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-005 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a pair of standing stones [S1]; each stone is only about 20 cm thick [S4]; the stones stand about 3 m apart [S5]; they stand on an open grassy place [S5]; they are thought to date from the Bronze Age [S2]; they stand between two low hills [S5]; they are aligned in a northeast-southwest direction [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two stones stand here as a pair. [SUPPORTED: https://cadw.gov.wales/visit/places-to-visit/penrhosfeilw-standing-stones]; The two stones stand about 3 m apart. [SUPPORTED: https://coflein.gov.uk/en/site/95537/]; The stones are only about 20 cm thick. [SUPPORTED: https://coflein.gov.uk/en/site/95537/]; The stones stand on open grass. [UNVERIFIABLE, no proving quote: None]; The pair is thought to date from the Bronze Age. [SUPPORTED: https://cadw.gov.wales/visit/places-to-visit/penrhosfeilw-standing-stones]; The pair rises between two low hills. [SUPPORTED: https://coflein.gov.uk/en/site/95537/]; The pair is lined up northeast to southwest. [SUPPORTED: http://www.stone-circles.org.uk/stone/penrhosfeilw.htm]"}]'::jsonb),
    ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', 'A rectangular stony coffin was dug up here during Japanese rule. The site dates back 3,000 years, and further study by Academia Sinica led to the discovery of a giant stone pile.', NULL, 'teaser-card-s043-rollback:b8f4c5f4-c567-4605-9f3d-9475d2db6362:card_description', 'rollback of teaser-card-s043: card_description None restored on Dulan Site', '48acb9808695d0cc571b2889f4db6b1421d5398f7f6ad30db692f8080fc3277e|fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4|fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-016", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A rectangular stony coffin was dug up here during Japanese rule. The site dates back 3,000 years, and further study by Academia Sinica led to the discovery of a giant stone pile."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a rectangular stony coffin was excavated at the site [S2]; it was excavated during Japanese rule [S2]; the site dates back 3,000 years [S4]; Academia Sinica carried out further investigation [S3]; that investigation led to the discovery of a giant stone pile [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-028 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A rectangular stony coffin was dug up here. [SUPPORTED: https://tour.taitung.gov.tw/en/attraction/details/607]; The coffin was dug up during Japanese rule. [SUPPORTED: https://tour.taitung.gov.tw/en/attraction/details/607]; The site dates back 3,000 years. [SUPPORTED: https://web.archive.org/web/20110123234719/http://tour.taitung.gov.tw/ch/AllInOne_Show.aspx?path=171&guid=b3a551fd-ef40-4915-943a-005157e9fd63&lang=zh-tw]; Further study was carried out by Academia Sinica. [SUPPORTED: https://tour.taitung.gov.tw/en/attraction/details/607]; The further study led to the discovery of a giant stone pile. [SUPPORTED: https://tour.taitung.gov.tw/en/attraction/details/607]"}]'::jsonb),
    ('bf30fac5-d015-46c4-b340-74e5614ce274'::uuid, 'card_description', 'Two nearly identical seated human figures lay by a large pyramid or hill. Apparently undisturbed since Pre-Classic times, the pair is called among the greatest works of Olmec art.', 'Beside a pyramid-hill in Veracruz, El Azuzul kept two pairs of Olmec sculptures intact and apparently undisturbed since Pre-Classic times, among them two nearly identical seated figures.', 'teaser-card-s043-rollback:bf30fac5-d015-46c4-b340-74e5614ce274:card_description', 'rollback of teaser-card-s043: card_description ''Beside a pyramid-hill in Veracruz, El Azuzul kept two pairs of Olmec sculptures intact and apparently undisturbed since Pre-Classic times, among them two nearly identical seated figures.'' restored on El Azuzul', '09f88c9c399095f0ed371a8dd9a8e7cd3d1f1364b4ad634947d0f73ca53d265a|6ff234fcc2acd02752d18bae53f0797d666799c5c98412e545d45f5819ea3063|6ff234fcc2acd02752d18bae53f0797d666799c5c98412e545d45f5819ea3063', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two nearly identical seated human figures lay by a large pyramid or hill. Apparently undisturbed since Pre-Classic times, the pair is called among the greatest works of Olmec art."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-006 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "two nearly identical seated human figures were found at the site [S6, S7]; they were found by a large pyramid or hill [S6]; they were apparently undisturbed since Pre-Classic times [S6]; the pair is described as among the greatest works of Olmec art [S7]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-029 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two nearly identical human figures lay at this site [SUPPORTED: https://web.archive.org/web/20090305155847/http://www.doaks.org/Social/social07.pdf]; The two figures are seated [SUPPORTED: https://web.archive.org/web/20090305155847/http://www.doaks.org/Social/social07.pdf]; The figures lay by a large pyramid or hill [SUPPORTED: https://web.archive.org/web/20090305155847/http://www.doaks.org/Social/social07.pdf]; The pair was apparently undisturbed since they were placed [SUPPORTED: https://web.archive.org/web/20090305155847/http://www.doaks.org/Social/social07.pdf]; The pair dates from Pre-Classic times [SUPPORTED: https://web.archive.org/web/20090305155847/http://www.doaks.org/Social/social07.pdf]; The pair is called among the greatest works of Olmec art [SUPPORTED: https://es.wikipedia.org/wiki/El_Azuzul]"}]'::jsonb),
    ('bfe38998-f394-4d5e-9a90-1fe222f8f106'::uuid, 'card_description', 'In 1627, a runestone turned up inside the wall of a church yard. The stone carries runes on two sides and is possibly the country''s oldest record of burial rites and inheritance.', 'Found in 1627 in a churchyard wall, the Tune Stone carries Proto-Norse runes from circa 200–450 AD, possibly the oldest Norwegian attestation of burial rites, inheritance and beer.', 'teaser-card-s043-rollback:bfe38998-f394-4d5e-9a90-1fe222f8f106:card_description', 'rollback of teaser-card-s043: card_description ''Found in 1627 in a churchyard wall, the Tune Stone carries Proto-Norse runes from circa 200–450 AD, possibly the oldest Norwegian attestation of burial rites, inheritance and beer.'' restored on Tune Stone', '3a7b5628faf96f903ae2154fc5ade0fcabf9186e013cfd4e288b51c8f2b06e50|476201755d9faa25a5e6894e8bbef5c7a313ddae7229dade8d7531c35c6cd7af|476201755d9faa25a5e6894e8bbef5c7a313ddae7229dade8d7531c35c6cd7af', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1627, a runestone turned up inside the wall of a church yard. The stone carries runes on two sides and is possibly the country''s oldest record of burial rites and inheritance."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the stone was discovered in 1627 [S3]; it is a runestone [S1]; it was found in a churchyard wall [S3]; the stone carries inscriptions on two sides [S6]; it is possibly the country''s oldest attestation of burial rites [S5]; it is possibly the country''s oldest attestation of inheritance [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1627, a runestone turned up inside the wall of a church yard [SUPPORTED: https://snl.no/Tunesteinen]; The stone is a runestone [SUPPORTED: https://snl.no/Tunesteinen]; The runestone turned up in 1627 [SUPPORTED: https://snl.no/Tunesteinen]; It turned up inside the wall of a church yard [SUPPORTED: https://snl.no/Tunesteinen]; The stone carries runes on two sides [SUPPORTED: https://snl.no/Tunesteinen]; The stone is possibly the country''s oldest record of burial rites [SUPPORTED: https://snl.no/Tunesteinen]; The stone is possibly the country''s oldest record of inheritance [SUPPORTED: https://snl.no/Tunesteinen]"}]'::jsonb),
    ('c34bf073-ed1e-4626-8cc8-8cbd724d9b93'::uuid, 'card_description', 'In 1945 this standing stone fell over, and it was raised again after a small dig. The dig showed the stone stood in a setting of quartz pebbles, with two small hollows below.', 'On the summit of St Breock Downs stands the St Breock Downs Monolith, the largest and heaviest prehistoric menhir in Cornwall, around 16.5 tonnes of shale set among quartz pebbles.', 'teaser-card-s043-rollback:c34bf073-ed1e-4626-8cc8-8cbd724d9b93:card_description', 'rollback of teaser-card-s043: card_description ''On the summit of St Breock Downs stands the St Breock Downs Monolith, the largest and heaviest prehistoric menhir in Cornwall, around 16.5 tonnes of shale set among quartz pebbles.'' restored on St Breock Downs Monolith', '7558bf3ec69ea0a2b3f61ac8acdcab1e85806c4487ec9467ff46742d30b776de|9b37fe1152c8a4d9d9d99625380bd698b36c363377cfaa6fcbadb492ba101abf|9b37fe1152c8a4d9d9d99625380bd698b36c363377cfaa6fcbadb492ba101abf', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1945 this standing stone fell over, and it was raised again after a small dig. The dig showed the stone stood in a setting of quartz pebbles, with two small hollows below."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it is a standing stone [S1]; it fell over in 1945 [S7]; it was re-erected after a small excavation [S7]; the excavation showed the stone stood in a setting of quartz pebbles [S8]; two small hollows lay below that setting [S8]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is a standing stone [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]; In 1945 this standing stone fell over [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]; It was raised again [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]; The raising followed a small dig [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]; The dig showed the stone stood in a setting of quartz pebbles [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]; The dig showed two small hollows below the setting [SUPPORTED: https://www.english-heritage.org.uk/visit/places/st-breock-downs-monolith/history/]"}]'::jsonb),
    ('c4bb47e2-6e2e-49e6-a17b-e9c2ad9c9129'::uuid, 'card_description', 'Only four of the original nine stones still stand upright in this circle. Close by lies an Early Christian site, and a small ruined church stands beside another upright stone with a bullaun.', 'Today only four upright stones of the original nine remain at Templebryan Stone Circle, The Druid''s Temple. Nearby, a small ruined church stands beside a stone with a bullaun.', 'teaser-card-s043-rollback:c4bb47e2-6e2e-49e6-a17b-e9c2ad9c9129:card_description', 'rollback of teaser-card-s043: card_description "Today only four upright stones of the original nine remain at Templebryan Stone Circle, The Druid''s Temple. Nearby, a small ruined church stands beside a stone with a bullaun." restored on Templebryan Stone Circle', '3f9bbaabfae676f247c11e9b4da51f8c7f9dfc42b07b21320284cbb00af35551|824f4aaac1f9ae8bee37ede31960004370813e7f054aa48a30e748488d1d2c3c|824f4aaac1f9ae8bee37ede31960004370813e7f054aa48a30e748488d1d2c3c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Only four of the original nine stones still stand upright in this circle. Close by lies an Early Christian site, and a small ruined church stands beside another upright stone with a bullaun."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it is a stone circle [S1]; it originally had nine stones [S3]; only four stones still stand upright today [S3]; an Early Christian site lies close by [S2]; there is a small ruined church nearby [S4]; the church is beside another upright stone with a bullaun [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This is a stone circle [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; Only four stones still stand upright in this circle [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; The circle originally had nine stones [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; Close by lies an Early Christian site [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; A small ruined church stands beside another upright stone [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; The church is small [SUPPORTED: https://www.megalithicireland.com/Templebryan%20Ogham%20Stone%20,%20Cork.html]; The church is ruined [SUPPORTED: https://duchasclonakiltyheritage.ie/gallery/Chap.%206%20O''Leary%202015.pdf]; A bullaun lies with the upright stone [SUPPORTED: https://www.megalithicireland.com/Templebryan%20Ogham%20Stone%20,%20Cork.html]"}]'::jsonb),
    ('c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba'::uuid, 'card_description', 'In 1826 a river gave up this decorated bronze facing from the Iron Age. Small rivet holes and stains suggest that a leather wild boar with long legs once sat around the central dome.', 'Found in the River Witham in 1826, the Witham Shield is Iron Age bronze of La Tène style. Small rivet holes and stains hint at a long-legged leather wild boar once riveted to its face.', 'teaser-card-s043-rollback:c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba:card_description', 'rollback of teaser-card-s043: card_description ''Found in the River Witham in 1826, the Witham Shield is Iron Age bronze of La Tène style. Small rivet holes and stains hint at a long-legged leather wild boar once riveted to its face.'' restored on Witham Shield', 'f4364e3afb4acb4041d3990be3db7cb790e2c5ec2e3bc313878da03ab30d5080|3794947896b65dd2126e525584bf97ffb5273b90f707b6afe0cc49e6e2bd93b7|3794947896b65dd2126e525584bf97ffb5273b90f707b6afe0cc49e6e2bd93b7', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1826 a river gave up this decorated bronze facing from the Iron Age. Small rivet holes and stains suggest that a leather wild boar with long legs once sat around the central dome."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it was found in a river in 1826 [S2]; it is a decorated bronze facing [S1]; it dates from the Iron Age [S1]; small rivet holes and staining suggest a leather long-legged wild boar was once fixed around the central dome [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1826 a river gave up this object [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]; It is a decorated bronze facing [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]; It dates from the Iron Age [SUPPORTED: https://www.worldhistory.org/article/1686/celtic-bronze-shields/]; Small rivet holes suggest that a boar figure was once fixed to it [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]; Stains on the bronze suggest the boar figure [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]; The boar figure was made of leather [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]; The figure was a wild boar with long legs [SUPPORTED: https://www.worldhistory.org/article/1686/celtic-bronze-shields/]; The boar once sat around the central dome [SUPPORTED: https://artsandculture.google.com/asset/the-witham-shield/iwHkBC35l--IXQ?hl=en]"}]'::jsonb),
    ('cc7e7e8a-ad91-4001-9849-bfcd41168369'::uuid, 'card_description', 'Four stone and earth ramparts curve in a half circle around this Iron Age enclosure. A steep slope defends the south side, while quarrying has left just one rampart on the east.', 'On a Northumberland hillside, the Slate Hill Settlement shields the north and west of its Iron Age enclosure with four concentric ramparts of stone and earth; a steep slope guards the south.', 'teaser-card-s043-rollback:cc7e7e8a-ad91-4001-9849-bfcd41168369:card_description', 'rollback of teaser-card-s043: card_description ''On a Northumberland hillside, the Slate Hill Settlement shields the north and west of its Iron Age enclosure with four concentric ramparts of stone and earth; a steep slope guards the south.'' restored on Slate Hill Settlement', '946fa4fa5ce12115f28d309da2d129dff46a578d0a8fd1d3ebdbf9f345772094|3e13dba5e65339ad64d6be8e13e348241226c8bd763b586ba96fa2e8cfb62b96|3e13dba5e65339ad64d6be8e13e348241226c8bd763b586ba96fa2e8cfb62b96', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Four stone and earth ramparts curve in a half circle around this Iron Age enclosure. A steep slope defends the south side, while quarrying has left just one rampart on the east."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there are four ramparts [S4]; the ramparts are of stone and earth [S5]; they form a semicircle around the enclosure [S4]; it is an Iron Age enclosure [S2, S4]; a steep slope defends the south side [S6]; quarrying affected the east side, where one rampart remains [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "There are four ramparts around this enclosure [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; The ramparts curve in a half circle [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; The ramparts are of stone and earth [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; The enclosure dates from the Iron Age [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; A steep slope defends the south side [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; Just one rampart remains on the east [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]; Quarrying caused the loss of the other ramparts on the east [SUPPORTED: https://keystothepast.info/search-records/results-of-search/results-of-search-2/Site-Details/?PRN=N10578]"}]'::jsonb),
    ('cca3b72c-8ad4-481b-838f-64bc69cf11a0'::uuid, 'card_description', 'For almost two thousand years, travellers have passed these large Roman mounds. They form the largest surviving Roman barrow group in their country, right beside the old Great North Road.', 'For almost two thousand years, travellers along the Roman road that eventually became the Great North Road have passed Six Hills, a collection of Roman barrows in Stevenage, Hertfordshire.', 'teaser-card-s043-rollback:cca3b72c-8ad4-481b-838f-64bc69cf11a0:card_description', 'rollback of teaser-card-s043: card_description ''For almost two thousand years, travellers along the Roman road that eventually became the Great North Road have passed Six Hills, a collection of Roman barrows in Stevenage, Hertfordshire.'' restored on Six Hills', '48ca4e76da704c5f37efe4df23d3e38f888d5089401781cbf0dedc402dd2f329|8da0d34bf0105034ccce992d4ef0f4e4a533af9be9191e6083c5387f27d94de3|8da0d34bf0105034ccce992d4ef0f4e4a533af9be9191e6083c5387f27d94de3', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "For almost two thousand years, travellers have passed these large Roman mounds. They form the largest surviving Roman barrow group in their country, right beside the old Great North Road."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "for almost two thousand years travellers have passed these mounds [S4]; the mounds are large [S4]; they are Roman (barrows) [S1]; they form the largest surviving Roman barrow group in their country [S3]; they lie beside the old Great North Road [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-030 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "For almost two thousand years, travellers have passed these mounds [SUPPORTED: https://greatnorthroad.co.uk/six-hills-stevenage]; The mounds are Roman [SUPPORTED: https://www1.leiza.de/transformation/unitedkingdom/gravemonuments/gravemonumentsinbritain.htm]; The mounds are large [UNVERIFIABLE, no proving quote: None]; They form the largest surviving Roman barrow group in their country [SUPPORTED: https://greatnorthroad.co.uk/six-hills-stevenage]; They lie right beside the old Great North Road [SUPPORTED: https://greatnorthroad.co.uk/six-hills-stevenage]"}]'::jsonb),
    ('ce979635-b9c3-4645-838d-a7a30da06854'::uuid, 'card_description', 'A massive triangular lintel tops the entrance of this coastal ruin, never excavated. Much rubble has fallen into its centre, yet old drawings show the structure had survived very well.', 'On a steep knoll near Shetland''s cliffs and sea, the unexcavated Broch of Culswick keeps a massive triangular lintel stone over its entrance, the passage behind it nearly filled with debris.', 'teaser-card-s043-rollback:ce979635-b9c3-4645-838d-a7a30da06854:card_description', 'rollback of teaser-card-s043: card_description "On a steep knoll near Shetland''s cliffs and sea, the unexcavated Broch of Culswick keeps a massive triangular lintel stone over its entrance, the passage behind it nearly filled with debris." restored on Broch of Culswick', '2a879cbb18603e5911953e838cf90d07bc4fa4af97ea6f47768021924d1270ce|1a1d4b8f56bec17b84cb2f81bd078754843187dcbd0a6982c3dced34592548a2|1a1d4b8f56bec17b84cb2f81bd078754843187dcbd0a6982c3dced34592548a2', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-017", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A massive triangular lintel tops the entrance of this coastal ruin, never excavated. Much rubble has fallen into its centre, yet old drawings show the structure had survived very well."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a massive triangular lintel stone sits over the entrance [S3]; it is coastal [S1]; it is a ruin (much rubble has fallen in) [S2]; it has never been excavated [S1]; much rubble has fallen into its centre [S2]; old drawings show the structure had survived very well up to their time [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A massive triangular lintel tops the entrance of this ruin [SUPPORTED: https://portal.historicenvironment.scot/designation/SM2055]; The ruin is coastal [SUPPORTED: https://www.shetlandamenity.org/off-the-beaten-track-11-in-search-of-brochs]; The ruin has never been excavated [SUPPORTED: https://portal.historicenvironment.scot/designation/SM2055]; Much rubble has fallen into its centre [SUPPORTED: https://www.shetlandamenity.org/off-the-beaten-track-11-in-search-of-brochs]; Old drawings of the structure exist [SUPPORTED: https://www.shetlandamenity.org/off-the-beaten-track-11-in-search-of-brochs]; The old drawings show the structure had survived very well [SUPPORTED: https://portal.historicenvironment.scot/designation/SM2055]"}]'::jsonb),
    ('cff3c769-e793-40f3-897c-4b085cdf9b56'::uuid, 'card_description', 'Defensive walls of stone blocks ring an ancient hamlet atop this mound. The man who explored the site, N. G. Majumdar, is also the one who gave the mound its name.', 'Ali Murad Mound lies 20 miles southwest of Dadu. At its top, an ancient hamlet was found ringed by defensive walls of stone blocks, and N. G. Majumdar explored and named the site.', 'teaser-card-s043-rollback:cff3c769-e793-40f3-897c-4b085cdf9b56:card_description', 'rollback of teaser-card-s043: card_description ''Ali Murad Mound lies 20 miles southwest of Dadu. At its top, an ancient hamlet was found ringed by defensive walls of stone blocks, and N. G. Majumdar explored and named the site.'' restored on Ali Murad Mound', '3aa8a241aa84f46235c455ceb7740049b574b963ad74832b4e2ea8017f2c0724|5c73a216f6c6663bb1201bbae37803270a5a954989f25c50cb8178212e7fb4ed|5c73a216f6c6663bb1201bbae37803270a5a954989f25c50cb8178212e7fb4ed', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Defensive walls of stone blocks ring an ancient hamlet atop this mound. The man who explored the site, N. G. Majumdar, is also the one who gave the mound its name."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a mound [S5]; an ancient hamlet lies at the top of the mound [S5]; the hamlet is surrounded by defensive walls [S5]; the walls are built of stone blocks [S5]; N. G. Majumdar explored the site [S2]; N. G. Majumdar named the site [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-031 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Walls ring a hamlet on this mound [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]; The walls are defensive [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]; The defensive walls are built of stone blocks [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]; The hamlet lies atop the mound [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]; The hamlet atop the mound is ancient [SUPPORTED: http://antiquities.sindhculture.gov.pk/index.php/mound/ali-murad-village-mound-johi-district-dadu]; N. G. Majumdar explored the site [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]; N. G. Majumdar is also the one who gave the mound its name [SUPPORTED: https://ur.wikipedia.org/wiki/%D8%B9%D9%84%DB%8C_%D9%85%D8%B1%D8%A7%D8%AF_%DA%A9%D8%A7_%D9%B9%DB%8C%D9%84%DB%81]"}]'::jsonb),
    ('d7a107f8-b228-48a7-97c5-081dc67c0469'::uuid, 'card_description', 'Torn down in the early second century BC, this building lived on inside another. Left unfinished, the building probably served as law courts, and a hall later rose over its foundations.', 'On the east side of the Agora of Athens, the Square Peristyle was begun around 300 BC but never finished. It probably served as law courts; the Stoa of Attalos rose on its foundations.', 'teaser-card-s043-rollback:d7a107f8-b228-48a7-97c5-081dc67c0469:card_description', 'rollback of teaser-card-s043: card_description ''On the east side of the Agora of Athens, the Square Peristyle was begun around 300 BC but never finished. It probably served as law courts; the Stoa of Attalos rose on its foundations.'' restored on Square Peristyle', 'f91cfaf906382df65d0ef93deddf832f4833a9290b688935f10c5610536552f1|b5251eba6875f826d9bcf0474b6023a4e7b47e7d275dead3ae238f225c5061af|b5251eba6875f826d9bcf0474b6023a4e7b47e7d275dead3ae238f225c5061af', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-008", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Torn down in the early second century BC, this building lived on inside another. Left unfinished, the building probably served as law courts, and a hall later rose over its foundations."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-008 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the building was demolished in the early second century BC [S4]; its material was reused in another building [S4]; the building was left unfinished [S2]; it probably served as law courts [S3]; a hall (the Stoa of Attalos) was later built over its foundations [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-012 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The building was torn down in the early second century BC [SUPPORTED: https://books.google.com/books/about/The_East_Side_of_the_Agora.html?id=ni2xAQAACAAJ]; The building lived on inside another (its materials were reused in another building) [SUPPORTED: https://books.google.com/books/about/The_East_Side_of_the_Agora.html?id=ni2xAQAACAAJ]; The building was left unfinished [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Law+Court+%28Square+Peristyle%29&object=Building]; The building probably served as law courts [SUPPORTED: https://books.google.com/books/about/The_East_Side_of_the_Agora.html?id=ni2xAQAACAAJ]; A hall later rose over its foundations [SUPPORTED: http://www.perseus.tufts.edu/hopper/artifact?name=Athens%2C+Law+Court+%28Square+Peristyle%29&object=Building]"}]'::jsonb),
    ('da471a32-1170-4d29-a63e-495436f6e326'::uuid, 'card_description', 'A skylight is thought to have let bodies in when a tomb was too full to enter. Four of these prehistoric tombs were cut into marlstone with stone tools, each with a round chamber.', 'Cut into marlstone with stone tools, the Artificial Caves of Alapraia end in round chambers under skylights, believed to have let bodies in when the corridors could no longer be used.', 'teaser-card-s043-rollback:da471a32-1170-4d29-a63e-495436f6e326:card_description', 'rollback of teaser-card-s043: card_description ''Cut into marlstone with stone tools, the Artificial Caves of Alapraia end in round chambers under skylights, believed to have let bodies in when the corridors could no longer be used.'' restored on Artificial Caves of Alapraia', '62aa1e8b35f2216d0dad44b19674dd6910be0c4895b6d2c95507bd706a7d39a4|67ad5cf74fd4e2528b456a73b91cd60ce7c9171ac255b69c3a5f61ba96f39030|67ad5cf74fd4e2528b456a73b91cd60ce7c9171ac255b69c3a5f61ba96f39030', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A skylight is thought to have let bodies in when a tomb was too full to enter. Four of these prehistoric tombs were cut into marlstone with stone tools, each with a round chamber."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "each tomb has a skylight [S3]; the skylight is believed to have let bodies be placed in the chamber [S4]; this was when the tomb was too full to enter through the corridor [S4]; there are four tombs [S1]; they are prehistoric [S1]; they were cut into marlstone [S1]; they were cut with stone tools [S1]; each has a round chamber [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "These tombs have a skylight in the chamber. [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=55517]; The skylight is thought to have let bodies in. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio-arqueologico/necropole-de-alapraia]; Bodies came in through the skylight when a tomb was too full to enter through its corridor. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio-arqueologico/necropole-de-alapraia]; There are four of these tombs. [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=55517]; These sites are tombs (a burial ground). [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=55517]; The tombs are prehistoric. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio-arqueologico/necropole-de-alapraia]; The tombs were cut into marlstone. [SUPPORTED: http://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=55517]; The tombs were cut with stone tools. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio-arqueologico/necropole-de-alapraia]; Each tomb has a round chamber. [SUPPORTED: https://cultura.cascais.pt/list/patrimonio-arqueologico/necropole-de-alapraia]"}]'::jsonb),
    ('db85cd62-288f-4142-9cad-f15532e4fe26'::uuid, 'card_description', 'Migrating peoples pressed harder on this Roman frontier after Dacia was abandoned. The frontier''s garrisons guarded provinces from attacks from the north, from camps and forts by a river.', 'Along the riverbank ran the Pannonian Limes, a Roman frontier of camps, watchtowers and fortified bridgeheads that guarded the Pannonian provinces against attacks from the north.', 'teaser-card-s043-rollback:db85cd62-288f-4142-9cad-f15532e4fe26:card_description', 'rollback of teaser-card-s043: card_description ''Along the riverbank ran the Pannonian Limes, a Roman frontier of camps, watchtowers and fortified bridgeheads that guarded the Pannonian provinces against attacks from the north.'' restored on Pannonian Limes', '48f98e87972b38be974863017812018de3698baa2eb53b4e0adc47a94ce73a92|73fcefded5bbd424d0f9a20417c0bf5724055fe84ae34efa2d1437c97457225c|73fcefded5bbd424d0f9a20417c0bf5724055fe84ae34efa2d1437c97457225c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Migrating peoples pressed harder on this Roman frontier after Dacia was abandoned. The frontier''s garrisons guarded provinces from attacks from the north, from camps and forts by a river."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-009 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a Roman frontier [S1]; migrating peoples put increasing pressure on it [S3]; this happened after Dacia was abandoned [S3]; the frontier''s garrisons guarded provinces against attacks from the north [S2]; the garrisons were based in camps and forts [S2, S4]; these camps and forts stood along a river [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-012 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Migrating peoples pressed harder on this frontier (the Pannonian Limes) after Dacia was abandoned [SUPPORTED: https://de.wikipedia.org/wiki/Pannonischer_Limes]; This is a Roman frontier [SUPPORTED: https://de.wikipedia.org/wiki/Pannonischer_Limes]; Dacia was abandoned [SUPPORTED: https://www.arub.cz/wp-content/uploads/ROMAN-LEGACY_Roman-Danube-Limes_handbook-for-tourist-guides-4.pdf]; The frontier''s garrisons guarded the provinces [SUPPORTED: https://de.wikipedia.org/wiki/Pannonischer_Limes]; The attacks the garrisons guarded against came from the north [SUPPORTED: https://www.arub.cz/wp-content/uploads/ROMAN-LEGACY_Roman-Danube-Limes_handbook-for-tourist-guides-4.pdf]; The garrisons were based in camps and forts [SUPPORTED: https://de.wikipedia.org/wiki/Pannonischer_Limes]; The camps and forts stood by a river [SUPPORTED: https://de.wikipedia.org/wiki/Pannonischer_Limes]"}]'::jsonb),
    ('dbd288ca-6fcc-4eaa-a346-a7b233b33955'::uuid, 'card_description', 'Bones in this Late Neolithic gallery grave show how many dead it once held. At least 235-250 people were placed in the grave over time, possibly over several centuries.', 'Over time, possibly over several centuries, the dead were laid in the Altendorf Megalithic Tomb, a Late Neolithic gallery grave in northern Hesse. Its bones speak of at least 235-250 people.', 'teaser-card-s043-rollback:dbd288ca-6fcc-4eaa-a346-a7b233b33955:card_description', 'rollback of teaser-card-s043: card_description ''Over time, possibly over several centuries, the dead were laid in the Altendorf Megalithic Tomb, a Late Neolithic gallery grave in northern Hesse. Its bones speak of at least 235-250 people.'' restored on Altendorf Megalithic Tomb', '5fd8826d5f0b7c0a26c491cccd76226026223f41b9fb573f526a76b86381218e|8b730f909ebda9e10ddfbf377f440559f6220dbf0672c22f9bd1f07de0df7d61|8b730f909ebda9e10ddfbf377f440559f6220dbf0672c22f9bd1f07de0df7d61', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Bones in this Late Neolithic gallery grave show how many dead it once held. At least 235-250 people were placed in the grave over time, possibly over several centuries."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-006 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "it is a Late Neolithic gallery grave [S2]; bones in the grave indicate the number of dead it held [S7]; at least 235-250 individuals were in the grave [S7]; the dead were placed in the grave over time [S6]; possibly over several centuries [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-032 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Bones in this grave (Altendorf) show how many dead it once held. [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Altendorf]; The grave is a gallery grave. [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Altendorf]; The grave is Late Neolithic. [SUPPORTED: https://en.wikipedia.org/wiki/Wartberg_culture]; At least 235-250 people were placed in the grave. [SUPPORTED: https://en.wikipedia.org/wiki/Wartberg_culture]; The dead were placed in the grave over time. [SUPPORTED: https://de.wikipedia.org/wiki/Galeriegrab_Altendorf]; The burials possibly spanned several centuries. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('dce4d9db-1bf4-4430-b5e6-2e13e63e4813'::uuid, 'card_description', 'A man of immense size, legend says, sharpened his scythe on this stone. He left the rock here in anger, and the stone''s twin sister was later destroyed for a large amount of sandstone.', 'Legend says a man of immense size sharpened his scythe on the Verziau of Gargantua and left it here in anger. The menhir''s twin sister was destroyed for its sandstone.', 'teaser-card-s043-rollback:dce4d9db-1bf4-4430-b5e6-2e13e63e4813:card_description', 'rollback of teaser-card-s043: card_description "Legend says a man of immense size sharpened his scythe on the Verziau of Gargantua and left it here in anger. The menhir''s twin sister was destroyed for its sandstone." restored on Verziau of Gargantua', 'e81c9877f5e2bae178abda76fbd7dea71e72b213f36d492570818f32a55921bf|41b3614a788f577e0d2cec5e3d7fe11bf70afa8f1a237ceafa0f79f5f08ac422|41b3614a788f577e0d2cec5e3d7fe11bf70afa8f1a237ceafa0f79f5f08ac422', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-018", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A man of immense size, legend says, sharpened his scythe on this stone. He left the rock here in anger, and the stone''s twin sister was later destroyed for a large amount of sandstone."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "according to legend, a man of immense size sharpened his scythe on this stone [S4]; according to legend, he left the rock here in anger [S4]; the stone had a twin sister [S3]; the twin was destroyed to extract a large amount of sandstone [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A man of immense size, legend says, sharpened his scythe on this stone. [SUPPORTED: https://fr.wikipedia.org/wiki/Verziau_de_Gargantua]; He left the rock here in anger. [SUPPORTED: https://fr.wikipedia.org/wiki/Verziau_de_Gargantua]; The stone had a twin sister. [SUPPORTED: https://fr.wikipedia.org/wiki/Verziau_de_Gargantua]; The stone''s twin sister was later destroyed for a large amount of sandstone. [SUPPORTED: https://fr.wikipedia.org/wiki/Verziau_de_Gargantua]; The stone (and its twin) is sandstone. [SUPPORTED: https://fr.wikipedia.org/wiki/Verziau_de_Gargantua]"}]'::jsonb),
    ('de97fdf7-80cc-425c-9c5b-b26b03310155'::uuid, 'card_description', 'Flint tools eroding out of a sandy cliff gave away this Mesolithic house. Its hearths held burnt nutshells, and some show only nut roasting, perhaps to keep food for times of scarcity.', 'Flint tools eroding from a sandy cliff revealed Howick House: a circle of post holes, hearths of burnt nutshells, a home built about 7600 BC and occupied for about 100 years.', 'teaser-card-s043-rollback:de97fdf7-80cc-425c-9c5b-b26b03310155:card_description', 'rollback of teaser-card-s043: card_description ''Flint tools eroding from a sandy cliff revealed Howick House: a circle of post holes, hearths of burnt nutshells, a home built about 7600 BC and occupied for about 100 years.'' restored on Howick House', '45e8e3937f71bf31dcc1352def9e8307b89b345f47c9dbfc852d133062aa800b|dd0b73e395c63f7ba2f3321e1fae26ff9fd75163badb6554933bf0cf9f99c3e4|dd0b73e395c63f7ba2f3321e1fae26ff9fd75163badb6554933bf0cf9f99c3e4', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Flint tools eroding out of a sandy cliff gave away this Mesolithic house. Its hearths held burnt nutshells, and some show only nut roasting, perhaps to keep food for times of scarcity."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site was revealed by flint tools eroding out of a sandy cliff [S2]; it is a Mesolithic house [S1, S3]; its hearths held burnt nutshells [S3]; some hearths show signs only of nut roasting [S5]; the cooking was perhaps meant to keep food for times of scarcity [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Flint tools eroding out of a sandy cliff gave away this house. [SUPPORTED: https://www.bbc.co.uk/history/ancient/archaeology/oldest_house_01.shtml]; It is a Mesolithic house. [SUPPORTED: https://antiquity.ac.uk/projgall/waddington295]; Its hearths held burnt nutshells. [SUPPORTED: https://www.bbc.co.uk/history/ancient/archaeology/oldest_house_01.shtml]; Some of the hearths show only nut roasting. [SUPPORTED: https://www.bbc.co.uk/history/ancient/archaeology/oldest_house_01.shtml]; The nut roasting was perhaps to keep food for times of scarcity. [SUPPORTED: https://www.bbc.co.uk/history/ancient/archaeology/oldest_house_01.shtml]"}]'::jsonb),
    ('dfc58d6f-44da-4159-b6e0-5fee86690841'::uuid, 'card_description', '2,000 years of digging stone left these limestone tunnels underground. The stone was favoured for cathedral and church door surrounds, and the Roman part has big arches holding up the roof.', '2,000 years of quarrying hollowed out Beer Quarry Caves in Devon. In the Roman section, cut by hand with picks and wooden wedges, large arches still hold up the limestone roof.', 'teaser-card-s043-rollback:dfc58d6f-44da-4159-b6e0-5fee86690841:card_description', 'rollback of teaser-card-s043: card_description ''2,000 years of quarrying hollowed out Beer Quarry Caves in Devon. In the Roman section, cut by hand with picks and wooden wedges, large arches still hold up the limestone roof.'' restored on Beer Quarry Caves', '9b633804a8319650ed25604614f51bbffa3d1cac6a00f37e3bda219a26767263|5408da355285c8e766866605a449fa87f8ec2f6046a5da19da76d9904e90d12c|5408da355285c8e766866605a449fa87f8ec2f6046a5da19da76d9904e90d12c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "2,000 years of digging stone left these limestone tunnels underground. The stone was favoured for cathedral and church door surrounds, and the Roman part has big arches holding up the roof."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tunnels resulted from 2,000 years of quarrying stone [S2]; the complex is a set of limestone tunnels underground [S1, S2]; the stone was favoured for cathedral and church door surrounds [S2]; there is a Roman section [S4]; the Roman section has large arches that support the roof [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "2,000 years of digging stone left these tunnels. [SUPPORTED: https://www.britainexpress.com/counties/devon/countryside/beer-quarry-caves.htm]; The tunnels are limestone. [SUPPORTED: https://www.exploredevon.info/activities/places/geology/beer-quarry-caves/]; The tunnels are underground. [SUPPORTED: https://www.exploredevon.info/activities/places/geology/beer-quarry-caves/]; The stone was favoured for cathedral and church work. [SUPPORTED: https://www.beerquarrycaves.co.uk/beer-stone/]; The stone was favoured for cathedral and church door surrounds. [SUPPORTED: https://britishlistedbuildings.co.uk/101325593-church-of-st-matthew-cheriton-fitzpaine]; The quarry has a Roman part. [SUPPORTED: https://www.exploredevon.info/activities/places/geology/beer-quarry-caves/]; The Roman part has big arches holding up the roof. [SUPPORTED: https://www.exploredevon.info/activities/places/geology/beer-quarry-caves/]"}]'::jsonb),
    ('e1b8b97e-0344-4248-8a0f-86d3b956c759'::uuid, 'card_description', 'A polished stone hammer turned up in this grave on a mountain slope. Digs also found burnt bone, flints and pottery at the U-shaped tomb, whose double walls hold a three-part chamber.', 'The tomb was excavated in the 1830s and then again in the 1940s; during this excavation, cremated bone, a polished stone hammer, flints and pottery were found.', 'teaser-card-s043-rollback:e1b8b97e-0344-4248-8a0f-86d3b956c759:card_description', 'rollback of teaser-card-s043: card_description ''The tomb was excavated in the 1830s and then again in the 1940s; during this excavation, cremated bone, a polished stone hammer, flints and pottery were found.'' restored on Ballyedmonduff Wedge Tomb', '3d08cd6f0e3896b29c73cc77ab4e91e180791cea52b63e2035bddbfea41fe565|b47b4601808b07d1add626d5bb28178be9c78e64c17b9786f076d61f1db8efae|b47b4601808b07d1add626d5bb28178be9c78e64c17b9786f076d61f1db8efae', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A polished stone hammer turned up in this grave on a mountain slope. Digs also found burnt bone, flints and pottery at the U-shaped tomb, whose double walls hold a three-part chamber."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a polished stone hammer was found in the tomb [S3]; it is a grave [S1]; it lies on a mountain slope [S2]; excavations also found burnt (cremated) bone [S3]; excavations also found flints [S3]; excavations also found pottery [S3]; the tomb is U-shaped [S4]; the tomb has double walling [S4]; its chamber is divided into three parts [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-033 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A polished stone hammer turned up in this grave. [SUPPORTED: https://curiousireland.ie/ballyedmunduff-wedge-tomb/]; The grave is on a mountain slope. [SUPPORTED: https://www.dublinmountains.ie/archaeology/archaeology/ballyedmonduff/]; Digs also found burnt bone at the tomb. [SUPPORTED: https://www.dublinmountains.ie/archaeology/archaeology/ballyedmonduff/]; Digs also found flints at the tomb. [SUPPORTED: https://www.dublinmountains.ie/archaeology/archaeology/ballyedmonduff/]; Digs also found pottery at the tomb. [SUPPORTED: https://www.dublinmountains.ie/archaeology/archaeology/ballyedmonduff/]; The tomb is U-shaped. [SUPPORTED: http://www.blather.net/theblather/2004/03/ballyedmonduff_wedgetomb_in_th/]; The tomb has double walls. [SUPPORTED: http://www.blather.net/theblather/2004/03/ballyedmonduff_wedgetomb_in_th/]; The double walls hold the tomb''s chamber. [SUPPORTED: http://www.blather.net/theblather/2004/03/ballyedmonduff_wedgetomb_in_th/]; The chamber is three-part. [SUPPORTED: http://www.blather.net/theblather/2004/03/ballyedmonduff_wedgetomb_in_th/]"}]'::jsonb),
    ('e1e4e79c-a9c4-4169-8fde-371c0df79061'::uuid, 'card_description', 'An inscription says two relatives renovated this theatre as a gift to the city. Built into a natural hill, the theatre was one of the first permanent stone theatres in the Roman empire.', 'In the Theatre Area of Pompeii, a Large Theatre built into a hill in the second century BC seated roughly 5,000 spectators, one of the first permanent stone theatres in the Roman empire.', 'teaser-card-s043-rollback:e1e4e79c-a9c4-4169-8fde-371c0df79061:card_description', 'rollback of teaser-card-s043: card_description ''In the Theatre Area of Pompeii, a Large Theatre built into a hill in the second century BC seated roughly 5,000 spectators, one of the first permanent stone theatres in the Roman empire.'' restored on Theatre Area of Pompeii', '066cef17acda09ea9f5a4e8f9edd09e4d15e8646bca1446d623296297af3f434|58c0bf2c881ea5914006fba369db2e079c96ee57d0f82290443b69a842405b29|58c0bf2c881ea5914006fba369db2e079c96ee57d0f82290443b69a842405b29', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An inscription says two relatives renovated this theatre as a gift to the city. Built into a natural hill, the theatre was one of the first permanent stone theatres in the Roman empire."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-009 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "an inscription in the theatre records the following [S6]; two relatives renovated the theatre [S6]; they presented it to the city as a gift [S6]; the theatre was built into a natural hill [S4]; it was one of the first permanent stone theatres in the Roman empire [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-012 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An inscription says two men renovated this theatre (the Large Theatre of Pompeii) [SUPPORTED: https://pompeiiinpictures.com/pompeiiinpictures/R8/8%2007%2020%20p3.htm]; The two men were relatives [SUPPORTED: https://pompeiiinpictures.com/pompeiiinpictures/R8/8%2007%2020%20p3.htm]; The renovation was a gift to the city (paid by the two men) [SUPPORTED: https://pompeiiinpictures.com/pompeiiinpictures/R8/8%2007%2020%20p3.htm]; The theatre was renovated [SUPPORTED: https://pompeiisites.org/en/archaeological-site/large-theatre/]; The theatre was built into a natural hill [SUPPORTED: https://pompeiisites.org/en/archaeological-site/large-theatre/]; The theatre was one of the first permanent stone theatres in the Roman empire [SUPPORTED: https://www.whitman.edu/theatre/theatretour/pompeii.theatre/commentary/pompeii.commentary.htm]"}]'::jsonb),
    ('e50a076d-5550-4c47-a49b-aced289dd4e0'::uuid, 'card_description', 'Roger Mercer''s digs turned up large amounts of Neolithic material on this chalk hill. A river parts the hill from the downs, and a Neolithic camp lies beside the prehistoric hill fort.', 'Hambledon Hill, a chalk outcrop in Dorset, bears a prehistoric hill fort beside a Neolithic causewayed camp, occupied while the area was still wooded, before the Bronze Age clearances.', 'teaser-card-s043-rollback:e50a076d-5550-4c47-a49b-aced289dd4e0:card_description', 'rollback of teaser-card-s043: card_description ''Hambledon Hill, a chalk outcrop in Dorset, bears a prehistoric hill fort beside a Neolithic causewayed camp, occupied while the area was still wooded, before the Bronze Age clearances.'' restored on Hambledon Hill', 'a2df36f4e961cf62aa9596a1a98670c526fd58c2122d01569c642bd6c78d79a6|964bae857d050d106f045c0d3c2b669c4b6bb8eb12651de536e2470298630857|964bae857d050d106f045c0d3c2b669c4b6bb8eb12651de536e2470298630857', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Roger Mercer''s digs turned up large amounts of Neolithic material on this chalk hill. A river parts the hill from the downs, and a Neolithic camp lies beside the prehistoric hill fort."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-009 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Roger Mercer excavated the site [S3]; the excavations produced large amounts of Neolithic material [S3]; the hill is chalk [S2]; a river separates the hill from the downs [S2]; a Neolithic camp lies beside the hill fort [S5]; the site is a prehistoric hill fort [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-012 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Roger Mercer dug on this hill (Hambledon Hill) [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3399.html]; Mercer''s digs turned up large amounts of Neolithic material [SUPPORTED: https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/hambledon-hill]; It is a chalk hill [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3399.html]; A river parts the hill from the downs [SUPPORTED: https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/hambledon-hill]; A Neolithic camp lies beside the hill fort [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3399.html]; The hill fort is prehistoric [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3399.html]"}]'::jsonb),
    ('e7c32c5c-3f26-483a-9d49-75ad5003c44b'::uuid, 'card_description', 'Diggers found human remains with signs of violent deaths at this Roman settlement. Carbon dates of two more skeletons, uncovered in 2004, fit the early 7th century as their time of death.', 'Found by chance in 1929 on the River Dee, the Heronbridge Roman Site had stone buildings and a quayside cut into the bedrock. Digs found human remains with evidence of violent deaths.', 'teaser-card-s043-rollback:e7c32c5c-3f26-483a-9d49-75ad5003c44b:card_description', 'rollback of teaser-card-s043: card_description ''Found by chance in 1929 on the River Dee, the Heronbridge Roman Site had stone buildings and a quayside cut into the bedrock. Digs found human remains with evidence of violent deaths.'' restored on Heronbridge Roman Site', '9504338cbb8e32d4ba76fa962e7efc40b14ba5966d25a7dfbd3f0edd0ce6d12b|56cb666d7e4f3c6d3bdbef030d783f77c9f2f8b959dc37c6be2d9e7922af166e|56cb666d7e4f3c6d3bdbef030d783f77c9f2f8b959dc37c6be2d9e7922af166e', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Diggers found human remains with signs of violent deaths at this Roman settlement. Carbon dates of two more skeletons, uncovered in 2004, fit the early 7th century as their time of death."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "excavations found human remains with evidence of violent deaths [S3]; the site is a Roman settlement [S1]; two further skeletons were uncovered in 2004 [S4]; their carbon dates are consistent with death in the early 7th century [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Diggers found human remains with signs of violent deaths at this site [SUPPORTED: http://www.yorkosteoarch.co.uk/pdf/1404.pdf]; This site is a Roman settlement [SUPPORTED: http://www.yorkosteoarch.co.uk/pdf/1404.pdf]; Two more skeletons were uncovered in 2004 [SUPPORTED: http://www.yorkosteoarch.co.uk/pdf/1404.pdf]; Carbon dates of the two skeletons fit the early 7th century as their time of death [SUPPORTED: http://www.yorkosteoarch.co.uk/pdf/1404.pdf]"}]'::jsonb),
    ('eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133'::uuid, 'card_description', 'A giant from Germanic myth was commonly said to have built this road. Folklore has clung to this Roman road, or possibly Neolithic structure, for several hundred years.', 'On the North York Moors lies Wade''s Causeway, a Roman road or possibly a Neolithic structure. For centuries folklore credited its building to Wade, a giant from Germanic mythology.', 'teaser-card-s043-rollback:eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133:card_description', 'rollback of teaser-card-s043: card_description "On the North York Moors lies Wade''s Causeway, a Roman road or possibly a Neolithic structure. For centuries folklore credited its building to Wade, a giant from Germanic mythology." restored on Wade''s Causeway', '0b89eb4ae86a20e017e19ade31852c3bbad45d9c6a148fac7bb1b958d5cc351a|37759757594e854b209f8f8978239e15658bd251b63b56913ad5902335a44fb0|37759757594e854b209f8f8978239e15658bd251b63b56913ad5902335a44fb0', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A giant from Germanic myth was commonly said to have built this road. Folklore has clung to this Roman road, or possibly Neolithic structure, for several hundred years."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "its construction was commonly attributed to a giant [S3]; the giant is a figure from Germanic mythology [S3]; it is a Roman road, or possibly a Neolithic structure [S1]; it has been the subject of folklore for several hundred years [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A giant (Wade) was commonly said to have built this road [SUPPORTED: https://www.maltonmuseum.co.uk/2021/06/26/wades-causeway-a-roman-road/]; The giant is from Germanic myth [SUPPORTED: https://en.wikipedia.org/wiki/Wade_(folklore)]; This is a Roman road, or possibly a Neolithic structure [SUPPORTED: https://www.english-heritage.org.uk/visit/places/wheeldale-roman-road/history/]; Folklore has clung to this road for several hundred years [SUPPORTED: https://www.english-heritage.org.uk/visit/places/wheeldale-roman-road/history/]"}]'::jsonb),
    ('eb752f57-8327-43bc-b6c4-98fa1f0a7ac2'::uuid, 'card_description', 'A small beaker with barbed-wire decoration lay inside this stone tomb. The beaker, from the early Bronze Age, suggests the site was used for around 1,000 years, perhaps with breaks.', 'From around 3000 BC, the Hartberg Megalithic Tomb held bones and a small beaker that suggests use, perhaps with interruptions, for around 1,000 years. Iron Age builders took its slabs.', 'teaser-card-s043-rollback:eb752f57-8327-43bc-b6c4-98fa1f0a7ac2:card_description', 'rollback of teaser-card-s043: card_description ''From around 3000 BC, the Hartberg Megalithic Tomb held bones and a small beaker that suggests use, perhaps with interruptions, for around 1,000 years. Iron Age builders took its slabs.'' restored on Hartberg Megalithic Tomb', '22a63d45cbfa1a20d46e56efb6ebe391f95f9b6051dd1d378c26a3219ee14d68|25531a452e397149b477cb3c3c180bd840fd6605b26871df4349a80c0160b4af|25531a452e397149b477cb3c3c180bd840fd6605b26871df4349a80c0160b4af', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-019", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A small beaker with barbed-wire decoration lay inside this stone tomb. The beaker, from the early Bronze Age, suggests the site was used for around 1,000 years, perhaps with breaks."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a small beaker lay inside the tomb [S4]; the beaker has barbed-wire decoration [S4]; it is a stone tomb [S1, S5]; the beaker is from the early Bronze Age [S4]; the beaker suggests the site was used for around 1,000 years [S4]; the use was perhaps with interruptions [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-034 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A beaker with barbed-wire decoration lay inside this stone tomb [SUPPORTED: https://de.wikipedia.org/wiki/Steinkiste_auf_dem_Hartberg]; The beaker is small [SUPPORTED: https://de.wikipedia.org/wiki/Steinkiste_auf_dem_Hartberg]; The site is a stone tomb [SUPPORTED: https://kulturdb.de/einobjekt.php?id=4836]; The beaker is from the early Bronze Age [SUPPORTED: https://kulturdb.de/einobjekt.php?id=4836]; The beaker suggests the site was used for around 1,000 years [SUPPORTED: https://kulturdb.de/einobjekt.php?id=4836]; The use was perhaps with breaks [SUPPORTED: https://kulturdb.de/einobjekt.php?id=4836]"}]'::jsonb),
    ('ee6608f3-f192-4c43-ab41-1f7ad3c9507d'::uuid, 'card_description', 'Local scouts carried on digging into this limestone cave in the 1950s. Later, researchers from Liverpool John Moores University dug there too, in a shaft with a steep tube at the bottom.', 'Some call it Fairy Cave: Dog Hole Cave near Storth is a shaft of 12 metres in Carboniferous Limestone, ending in a steep phreatic tube, where local scouts dug in the 1950s.', 'teaser-card-s043-rollback:ee6608f3-f192-4c43-ab41-1f7ad3c9507d:card_description', 'rollback of teaser-card-s043: card_description ''Some call it Fairy Cave: Dog Hole Cave near Storth is a shaft of 12 metres in Carboniferous Limestone, ending in a steep phreatic tube, where local scouts dug in the 1950s.'' restored on Dog Hole Cave', '0d14be72358ff1e76e15c3268360eca66a017e1da4595b8ab30d1af7d38cfba9|7d83ada80dd73d59bcbf3323616321b6cd0e677597cbeafd9cf83f1040a2a742|7d83ada80dd73d59bcbf3323616321b6cd0e677597cbeafd9cf83f1040a2a742', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-009", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Local scouts carried on digging into this limestone cave in the 1950s. Later, researchers from Liverpool John Moores University dug there too, in a shaft with a steep tube at the bottom."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-009 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "local scouts carried out further digging at the cave in the 1950s [S4]; the cave is in limestone [S3]; researchers from Liverpool John Moores University later dug there too [S4]; the cave is a shaft [S3]; a steeply dipping tube lies at the bottom of the shaft [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-013 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Local scouts carried on digging into this cave in the 1950s [SUPPORTED: https://www.nottingham.ac.uk/humanities/departments/classics-and-archaeology/research/research-projects/current-projects/2020-2005-dog-hole-cave-haverbrack.aspx]; The scouts carried on (continued) an earlier dig, the scouts being the local troop [SUPPORTED: https://bcra.org.uk/pub/candks/index.html?j=114]; This is a limestone cave [SUPPORTED: https://web.archive.org/web/20111028172238/http://www.ljmu.ac.uk/RCEAP/81121.htm]; Later, researchers from Liverpool John Moores University dug there too [SUPPORTED: https://web.archive.org/web/20111028172238/http://www.ljmu.ac.uk/RCEAP/81121.htm]; The dig was in a shaft [SUPPORTED: https://bcra.org.uk/pub/candks/index.html?j=114]; The shaft has a steep tube at the bottom [SUPPORTED: http://www.rrcpc.org.uk/newsletters/NL_V42_N2_A6.htm]"}]'::jsonb),
    ('f1a0b11e-e382-42dd-bfdd-4116409af9ca'::uuid, 'card_description', 'Two carved birds feed a chick on the arched entrance of these underground tombs. Cut into local limestone, they were first excavated in 1912, but a water main had already disturbed them.', 'Dug into Globigerina Limestone, the Ħal Resqun Catacombs open through an arched entrance carved with a peacock and a peahen feeding a chick, its doorway flanked by two engraved columns.', 'teaser-card-s043-rollback:f1a0b11e-e382-42dd-bfdd-4116409af9ca:card_description', 'rollback of teaser-card-s043: card_description ''Dug into Globigerina Limestone, the Ħal Resqun Catacombs open through an arched entrance carved with a peacock and a peahen feeding a chick, its doorway flanked by two engraved columns.'' restored on Ħal Resqun Catacombs', 'd6e2189e6ecd0ffc56bef655eccd42342657557a02e57cbdcf3a9575896f385e|5714f6a950e50be480eeca906f6eb60b49ef669941aed7577bd56a7aaddd38c7|5714f6a950e50be480eeca906f6eb60b49ef669941aed7577bd56a7aaddd38c7', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-010", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two carved birds feed a chick on the arched entrance of these underground tombs. Cut into local limestone, they were first excavated in 1912, but a water main had already disturbed them."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-010 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "two carved birds appear on the entrance [S4]; the birds are shown feeding a chick [S4]; the entrance is arched [S4]; the site is underground tombs (catacombs) [S1, S2]; the tombs are cut into local limestone [S2]; they were first excavated in 1912 [S3]; a water main had already disturbed them before that excavation [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-013 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two carved birds feed a chick on the arched entrance of these underground tombs [SUPPORTED: https://archsoc.org.mt/hal-resqun-catacomb/]; The entrance is arched [SUPPORTED: https://archsoc.org.mt/hal-resqun-catacomb/]; These are underground tombs [SUPPORTED: https://archsoc.org.mt/hal-resqun-catacomb/]; The tombs are cut into the rock [SUPPORTED: https://archsoc.org.mt/hal-resqun-catacomb/]; The rock they are cut into is local limestone [UNVERIFIABLE, no proving quote: None]; They were first excavated in 1912 [SUPPORTED: https://archsoc.org.mt/hal-resqun-catacomb/]; A water main had already disturbed them before they were first excavated [SUPPORTED: https://timesofmalta.com/articles/view/the-hal-resqun-catacomb.43266]"}]'::jsonb),
    ('f2b64b04-bcd7-4333-ac21-2641a667bef2'::uuid, 'card_description', 'Nine standing stones stand in a row, sorted by their height. Once there were eleven or twelve at this Iron Age grave field, which also holds about 45 graves and a stone ship.', 'Nine menhirs stand in a row at Stenehed, placed by height from 3.3 m to 1.4 m, beside about 45 graves, a stone circle and a stone ship of the Iron Age. Once there were eleven or twelve.', 'teaser-card-s043-rollback:f2b64b04-bcd7-4333-ac21-2641a667bef2:card_description', 'rollback of teaser-card-s043: card_description ''Nine menhirs stand in a row at Stenehed, placed by height from 3.3 m to 1.4 m, beside about 45 graves, a stone circle and a stone ship of the Iron Age. Once there were eleven or twelve.'' restored on Stenehed', '7c997d5b91ba4be06601f7977e2ccc15b3298aee66c32e236c83441cf5bc4020|eda3a0df9c37bf285292323596eb4f2d46ce208047b73f250f9cc8b0de0f2cc4|eda3a0df9c37bf285292323596eb4f2d46ce208047b73f250f9cc8b0de0f2cc4', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-020", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Nine standing stones stand in a row, sorted by their height. Once there were eleven or twelve at this Iron Age grave field, which also holds about 45 graves and a stone ship."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "nine standing stones stand at the site today [S3]; they stand in a row [S5]; they are sorted by their height [S5]; originally there were eleven or twelve of them [S3]; the site is an Iron Age grave field [S1]; it holds about 45 graves [S2]; it holds a stone ship [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Nine standing stones stand at the site today [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]; The standing stones stand in a row [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]; The stones are sorted by their height [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]; Once there were eleven or twelve standing stones [SUPPORTED: https://sv.wikipedia.org/wiki/Stenehed]; The site is an Iron Age grave field [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]; The grave field holds about 45 graves [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]; The grave field holds a stone ship [SUPPORTED: https://www.bohuslansmuseum.se/kunskapsbanken_bohuslans_historia/stenehed/]"}]'::jsonb),
    ('f5893102-13b9-44a0-bc87-8348f7da115c'::uuid, 'card_description', 'About 70% of the bronze finds at this fort are weapons. A sandstone wall here probably burned down during a battle, and the fort was later expanded into a strong hillfort.', 'On a hill spur near Kronach, the Heunischenburg is the oldest known and investigated stone fortification north of the Alps. Its sandstone wall probably burned down during a battle.', 'teaser-card-s043-rollback:f5893102-13b9-44a0-bc87-8348f7da115c:card_description', 'rollback of teaser-card-s043: card_description ''On a hill spur near Kronach, the Heunischenburg is the oldest known and investigated stone fortification north of the Alps. Its sandstone wall probably burned down during a battle.'' restored on Heunischenburg', '3167c7af1513ba17d6944a8c21b344f01bf18e1593dab148d013c17ac24be902|7fa771513c077de359f3d555cc334b3460d0fb341cb1d543a1998d826f121d12|7fa771513c077de359f3d555cc334b3460d0fb341cb1d543a1998d826f121d12', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-020", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "About 70% of the bronze finds at this fort are weapons. A sandstone wall here probably burned down during a battle, and the fort was later expanded into a strong hillfort."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a fort [S1, S4]; bronze finds were made at the fort [S8]; about 70% of the bronze finds are weapons [S8]; the fort had a sandstone wall [S6]; the wall probably burned down during a battle [S6]; the fort was later expanded into a strong hillfort [S7]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-035 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "About 70% of the bronze finds at this fort are weapons [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Heunbg-Zusammenfassung.htm]; The site is a fort [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Aus-Heunbg.htm]; There was a sandstone wall here [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Heunbg-Zusammenfassung.htm]; The sandstone wall probably burned down during a battle [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Heunbg-Zusammenfassung.htm]; The fort was later expanded [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Heunbg-Zusammenfassung.htm]; The expanded fort was a strong hillfort [SUPPORTED: http://www.landschaftsmuseum.de/Seiten/Ausgrab/Heunbg-Zusammenfassung.htm]"}]'::jsonb),
    ('fd94d469-92a0-4796-a7a8-64f925f01773'::uuid, 'card_description', 'Axe heads from a Neolithic quarry here have been found across the British Isles. The axes were roughed out here, finished at the sea shore and exported as far as south-east England.', 'At the foot of Tievebulliagh in the Glens of Antrim lay a Neolithic axe quarry. Porcellanite axes roughed out here were finished at the sea shore and found across the British Isles.', 'teaser-card-s043-rollback:fd94d469-92a0-4796-a7a8-64f925f01773:card_description', 'rollback of teaser-card-s043: card_description ''At the foot of Tievebulliagh in the Glens of Antrim lay a Neolithic axe quarry. Porcellanite axes roughed out here were finished at the sea shore and found across the British Isles.'' restored on Tievebulliagh', '1c5e6e6355e983bc9dd03607b3db98ecabf8bf8383758a2120d3e67d257cb364|da61b90c2d99bba3b0f42fe701eaaf2997aadcb454e516f4543423d8504691be|da61b90c2d99bba3b0f42fe701eaaf2997aadcb454e516f4543423d8504691be', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-020", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Axe heads from a Neolithic quarry here have been found across the British Isles. The axes were roughed out here, finished at the sea shore and exported as far as south-east England."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there was a Neolithic axe quarry here [S2]; axe heads from the quarry have been found across the British Isles [S3]; the axes were roughed out here [S5]; they were finished at the sea shore [S5]; they were exported as far as south-east England [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-036 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Axe heads from a Neolithic quarry here have been found across the British Isles. [SUPPORTED: https://www.newry.ie/history/neolithic-stone-axes-and-flint-scrapers-at-newry-museum]; There was a Neolithic quarry here. [SUPPORTED: https://www.newry.ie/history/neolithic-stone-axes-and-flint-scrapers-at-newry-museum]; The axes were roughed out here. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=6333459]; The axes were finished at the sea shore. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=6333459]; The axes were exported as far as south-east England. [SUPPORTED: https://www.newry.ie/history/neolithic-stone-axes-and-flint-scrapers-at-newry-museum]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 42;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s043-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s043-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s043-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 42 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('94f496b6-5e15-4a5a-9bd2-0cb1885864bf'::uuid, 'card_description', 'An iron folding chair turned up among the grave goods in these Roman mounds. Diggers in the 19th century also found human ashes inside glass vessels, kept in large wooden chests.'), ('951c140b-1698-4495-9c6b-c78254c2b4cd'::uuid, 'card_description', 'An upturned tree root sat at the heart of this timber circle. Around the root stood 55 split oak trunks, all but one with bark facing out; a trunk with a narrow Y fork let people in.'), ('99c67365-3376-46ae-9e60-0d2ec03bfff4'::uuid, 'card_description', 'Coins from Mark Anthony to Gratian lay in this walled spring. With them lay a relief of three water nymphs, the head of a male statue and ten altars to a goddess and Minerva.'), ('9fe64aa7-1b1a-4074-b6c2-f2d236938ab4'::uuid, 'card_description', 'A wooden structure of unknown use was found inside this small Roman fort. Its only gate faced north, toward the frontier, behind a rampart and a ditch 5 meters wide and 1.5 meters deep.'), ('a2b571fa-4aa3-4c23-b5f0-13c5552ce870'::uuid, 'card_description', 'Francisco Pizarro took this royal Inca estate for himself in the 1530s. It had belonged to an Inca emperor, and the estate ran for 15 kilometres up and down the Sacred Valley.'), ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'card_description', 'Two crests once ran across the top of this warrior''s helmet and down its back. Dug up in 2008 from a burial of the first century BC, the helmet was the most remarkable object of the grave.'), ('a42d9ff4-6d8d-4cb2-bb1d-64b1c66cb290'::uuid, 'card_description', 'A groundsman clearing land for a runway found Iron Age metalwork. Over 150 objects came out of the peat, apparently placed in a small lake as offerings, the first an iron chain for slaves.'), ('a6492846-5963-4307-8ffc-ea06bb554b1e'::uuid, 'card_description', 'Upright stones shrink from south-west to north-east along this prehistoric tomb. The tomb measures about 4.5 by 2 metres, and the largest of its side stones stands at the entrance.'), ('a72bf9fc-f2ef-4f84-b322-f9707dac50f5'::uuid, 'card_description', 'Coastal erosion was believed to have largely destroyed this stone temple. In 2015, its remains turned out to survive, along with a previously unrecorded megalithic structure nearby.'), ('ab699722-9c7e-464a-b507-74a21078411c'::uuid, 'card_description', 'Iron furnaces and pottery kilns shared a Roman town with this temple. Remains from the late Iron Age date from 30 BC, and a Roman road 7 metres wide predates the one through the village.'), ('acec1746-35a0-4d0e-be03-1d240bad074c'::uuid, 'card_description', 'A pyramid over 10 metres high rises on a wooded hilltop here. The pyramid stands at the north end of at least three groups of ruins on a north-south line, about 18 kilometres from Tikal.'), ('ae3b5deb-3b9c-42ec-8610-445c99f5b1a8'::uuid, 'card_description', 'No evidence shows the Roman general in this hillfort''s name ever came here. The earthworks stretch 730 m from north to south, on a hill with the River Avon to the south.'), ('b43e7f32-5f59-4370-9cf0-43c3f159e4e3'::uuid, 'card_description', 'A carved stone slab was found in the northern group of this Maya site. Eleven residential areas lie in its two groups, and the site is considered a satellite of El Mirador.'), ('b69f338c-fb2b-4860-9935-61e93e27ddf3'::uuid, 'card_description', 'Only about 20 cm thick, two stones stand about 3 m apart on open grass. Thought to date from the Bronze Age, the pair rises between two low hills, lined up northeast to southwest.'), ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', 'A rectangular stony coffin was dug up here during Japanese rule. The site dates back 3,000 years, and further study by Academia Sinica led to the discovery of a giant stone pile.'), ('bf30fac5-d015-46c4-b340-74e5614ce274'::uuid, 'card_description', 'Two nearly identical seated human figures lay by a large pyramid or hill. Apparently undisturbed since Pre-Classic times, the pair is called among the greatest works of Olmec art.'), ('bfe38998-f394-4d5e-9a90-1fe222f8f106'::uuid, 'card_description', 'In 1627, a runestone turned up inside the wall of a church yard. The stone carries runes on two sides and is possibly the country''s oldest record of burial rites and inheritance.'), ('c34bf073-ed1e-4626-8cc8-8cbd724d9b93'::uuid, 'card_description', 'In 1945 this standing stone fell over, and it was raised again after a small dig. The dig showed the stone stood in a setting of quartz pebbles, with two small hollows below.'), ('c4bb47e2-6e2e-49e6-a17b-e9c2ad9c9129'::uuid, 'card_description', 'Only four of the original nine stones still stand upright in this circle. Close by lies an Early Christian site, and a small ruined church stands beside another upright stone with a bullaun.'), ('c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba'::uuid, 'card_description', 'In 1826 a river gave up this decorated bronze facing from the Iron Age. Small rivet holes and stains suggest that a leather wild boar with long legs once sat around the central dome.'), ('cc7e7e8a-ad91-4001-9849-bfcd41168369'::uuid, 'card_description', 'Four stone and earth ramparts curve in a half circle around this Iron Age enclosure. A steep slope defends the south side, while quarrying has left just one rampart on the east.'), ('cca3b72c-8ad4-481b-838f-64bc69cf11a0'::uuid, 'card_description', 'For almost two thousand years, travellers have passed these large Roman mounds. They form the largest surviving Roman barrow group in their country, right beside the old Great North Road.'), ('ce979635-b9c3-4645-838d-a7a30da06854'::uuid, 'card_description', 'A massive triangular lintel tops the entrance of this coastal ruin, never excavated. Much rubble has fallen into its centre, yet old drawings show the structure had survived very well.'), ('cff3c769-e793-40f3-897c-4b085cdf9b56'::uuid, 'card_description', 'Defensive walls of stone blocks ring an ancient hamlet atop this mound. The man who explored the site, N. G. Majumdar, is also the one who gave the mound its name.'), ('d7a107f8-b228-48a7-97c5-081dc67c0469'::uuid, 'card_description', 'Torn down in the early second century BC, this building lived on inside another. Left unfinished, the building probably served as law courts, and a hall later rose over its foundations.'), ('da471a32-1170-4d29-a63e-495436f6e326'::uuid, 'card_description', 'A skylight is thought to have let bodies in when a tomb was too full to enter. Four of these prehistoric tombs were cut into marlstone with stone tools, each with a round chamber.'), ('db85cd62-288f-4142-9cad-f15532e4fe26'::uuid, 'card_description', 'Migrating peoples pressed harder on this Roman frontier after Dacia was abandoned. The frontier''s garrisons guarded provinces from attacks from the north, from camps and forts by a river.'), ('dbd288ca-6fcc-4eaa-a346-a7b233b33955'::uuid, 'card_description', 'Bones in this Late Neolithic gallery grave show how many dead it once held. At least 235-250 people were placed in the grave over time, possibly over several centuries.'), ('dce4d9db-1bf4-4430-b5e6-2e13e63e4813'::uuid, 'card_description', 'A man of immense size, legend says, sharpened his scythe on this stone. He left the rock here in anger, and the stone''s twin sister was later destroyed for a large amount of sandstone.'), ('de97fdf7-80cc-425c-9c5b-b26b03310155'::uuid, 'card_description', 'Flint tools eroding out of a sandy cliff gave away this Mesolithic house. Its hearths held burnt nutshells, and some show only nut roasting, perhaps to keep food for times of scarcity.'), ('dfc58d6f-44da-4159-b6e0-5fee86690841'::uuid, 'card_description', '2,000 years of digging stone left these limestone tunnels underground. The stone was favoured for cathedral and church door surrounds, and the Roman part has big arches holding up the roof.'), ('e1b8b97e-0344-4248-8a0f-86d3b956c759'::uuid, 'card_description', 'A polished stone hammer turned up in this grave on a mountain slope. Digs also found burnt bone, flints and pottery at the U-shaped tomb, whose double walls hold a three-part chamber.'), ('e1e4e79c-a9c4-4169-8fde-371c0df79061'::uuid, 'card_description', 'An inscription says two relatives renovated this theatre as a gift to the city. Built into a natural hill, the theatre was one of the first permanent stone theatres in the Roman empire.'), ('e50a076d-5550-4c47-a49b-aced289dd4e0'::uuid, 'card_description', 'Roger Mercer''s digs turned up large amounts of Neolithic material on this chalk hill. A river parts the hill from the downs, and a Neolithic camp lies beside the prehistoric hill fort.'), ('e7c32c5c-3f26-483a-9d49-75ad5003c44b'::uuid, 'card_description', 'Diggers found human remains with signs of violent deaths at this Roman settlement. Carbon dates of two more skeletons, uncovered in 2004, fit the early 7th century as their time of death.'), ('eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133'::uuid, 'card_description', 'A giant from Germanic myth was commonly said to have built this road. Folklore has clung to this Roman road, or possibly Neolithic structure, for several hundred years.'), ('eb752f57-8327-43bc-b6c4-98fa1f0a7ac2'::uuid, 'card_description', 'A small beaker with barbed-wire decoration lay inside this stone tomb. The beaker, from the early Bronze Age, suggests the site was used for around 1,000 years, perhaps with breaks.'), ('ee6608f3-f192-4c43-ab41-1f7ad3c9507d'::uuid, 'card_description', 'Local scouts carried on digging into this limestone cave in the 1950s. Later, researchers from Liverpool John Moores University dug there too, in a shaft with a steep tube at the bottom.'), ('f1a0b11e-e382-42dd-bfdd-4116409af9ca'::uuid, 'card_description', 'Two carved birds feed a chick on the arched entrance of these underground tombs. Cut into local limestone, they were first excavated in 1912, but a water main had already disturbed them.'), ('f2b64b04-bcd7-4333-ac21-2641a667bef2'::uuid, 'card_description', 'Nine standing stones stand in a row, sorted by their height. Once there were eleven or twelve at this Iron Age grave field, which also holds about 45 graves and a stone ship.'), ('f5893102-13b9-44a0-bc87-8348f7da115c'::uuid, 'card_description', 'About 70% of the bronze finds at this fort are weapons. A sandstone wall here probably burned down during a battle, and the fort was later expanded into a strong hillfort.'), ('fd94d469-92a0-4796-a7a8-64f925f01773'::uuid, 'card_description', 'Axe heads from a Neolithic quarry here have been found across the British Isles. The axes were roughed out here, finished at the sea shore and exported as far as south-east England.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s043-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
